<?php require_once __DIR__ . '/_common.php';
if(isset($_POST['delete_product'])){ $id=(int)$_POST['product_id']; $s=$conn->prepare("SELECT image FROM products WHERE id=? AND vendor_id=?");$s->bind_param('ii',$id,$vendor_id);$s->execute();$r=$s->get_result();if($p=$r->fetch_assoc()){ $d=$conn->prepare("DELETE FROM products WHERE id=? AND vendor_id=?");$d->bind_param('ii',$id,$vendor_id);if($d->execute()&&!empty($p['image'])&&is_file(__DIR__.'/../assets/uploads/'.$p['image']))@unlink(__DIR__.'/../assets/uploads/'.$p['image']); } }
$s=$conn->prepare("SELECT * FROM products WHERE vendor_id=? ORDER BY created_at DESC");$s->bind_param('i',$vendor_id);$s->execute();$products=$s->get_result();
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Products - Bazario</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css" rel="stylesheet"><link href="../assets/css/theme.css" rel="stylesheet"><link href="style.css" rel="stylesheet"></head><body><div class="container-fluid"><div class="row"><aside class="col-md-3 col-lg-2 px-0"><div class="sidebar p-3"><h4 class="text-white text-center mb-4"><i class="fas fa-store me-2"></i>Bazario</h4><nav class="nav flex-column"><a class="nav-link" href="dashboard.php">Dashboard</a><a class="nav-link active" href="products.php">My Products</a><a class="nav-link" href="add_product.php">Add Product</a><hr class="text-white-50"><a class="nav-link" href="../store.php">View Store</a><a class="nav-link" href="../logout.php">Logout</a></nav></div></aside><main class="col-md-9 col-lg-10"><div class="p-4"><div class="d-flex justify-content-between align-items-center mb-4"><div><h2 class="text-white">My Products</h2><p class="text-white-50">Update product details, stock and images.</p></div><a href="add_product.php" class="btn btn-brand"><i class="fas fa-plus me-2"></i>Add Product</a></div><div class="row g-4"><?php while($p=$products->fetch_assoc()): ?><div class="col-md-6 col-xl-4"><div class="product-card"><?php if(!empty($p['image'])&&is_file(__DIR__.'/../assets/uploads/'.$p['image'])):?><img class="product-image" src="../assets/uploads/<?=htmlspecialchars($p['image'])?>" alt="<?=htmlspecialchars($p['name'])?>"><?php else:?><div class="placeholder"><i class="fas fa-image"></i></div><?php endif;?><div class="p-3"><h5><?=htmlspecialchars($p['name'])?></h5><p class="text-white-50 small mb-2"><?=htmlspecialchars($p['category']??'')?></p><div class="d-flex justify-content-between mb-3"><strong>₹<?=number_format($p['price'],2)?></strong><span>Stock: <?=$p['stock']?></span></div><div class="d-flex gap-2"><a href="edit_product.php?id=<?=$p['id']?>" class="btn btn-brand flex-grow-1"><i class="fas fa-pen me-1"></i>Edit</a><form method="post" onsubmit="return confirm('Delete this product?')"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button name="delete_product" class="btn btn-outline-light"><i class="fas fa-trash"></i></button></form></div></div></div></div><?php endwhile;?></div></div></main></div></div></body></html>
